{
  "id": "world2-forrester-original-cla",
  "name": "World2 Forrester Original Model",
  "description": "Jay Forrester's original WORLD2 model from 1971. A five-sector global model examining interactions between population, capital investment, natural resources, pollution, and quality of life. Reference: Forrester, J. W. (1961). Industrial Dynamics. MIT Press. Source: https://systemdynamics.org/",
  "source": "https://mitpress.mit.edu/9780262560047/world-dynamics/",
  "reference": "Forrester, J.W. (1971). World Dynamics. Wright-Allen Press/MIT Press. Cambridge, MA.",
  "stocks": [
    {
      "id": "stock-pop",
      "name": "Population",
      "initial_value": 1650000000,
      "equation": "",
      "position": {
        "x": 100,
        "y": 200
      }
    },
    {
      "id": "stock-capital",
      "name": "Capital Investment",
      "initial_value": 400000000,
      "equation": "",
      "position": {
        "x": 300,
        "y": 200
      }
    },
    {
      "id": "stock-resources",
      "name": "Natural Resources",
      "initial_value": 900000000000,
      "equation": "",
      "position": {
        "x": 500,
        "y": 200
      }
    },
    {
      "id": "stock-pollution",
      "name": "Pollution",
      "initial_value": 200000000,
      "equation": "",
      "position": {
        "x": 300,
        "y": 350
      }
    },
    {
      "id": "stock-agric-frac",
      "name": "Capital in Agriculture Fraction",
      "initial_value": 0.2,
      "equation": "",
      "position": {
        "x": 100,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-births",
      "name": "Birth Rate",
      "equation": "Population * Birth_Rate_Normal * Birth_Rate_Multiplier",
      "from_stock": null,
      "to_stock": "stock-pop",
      "position": {
        "x": 50,
        "y": 200
      }
    },
    {
      "id": "flow-deaths",
      "name": "Death Rate",
      "equation": "Population * Death_Rate_Normal * Death_Rate_Multiplier",
      "from_stock": "stock-pop",
      "to_stock": null,
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "flow-capital-gen",
      "name": "Capital Generation",
      "equation": "Population * Capital_Generation_Normal * Capital_Generation_Multiplier",
      "from_stock": null,
      "to_stock": "stock-capital",
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-depreciation",
      "name": "Capital Depreciation",
      "equation": "Capital_Investment / Capital_Normal_Lifetime",
      "from_stock": "stock-capital",
      "to_stock": null,
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "flow-resource-use",
      "name": "Resource Usage",
      "equation": "Population * Resource_Usage_Normal * Resource_Usage_Multiplier",
      "from_stock": "stock-resources",
      "to_stock": null,
      "position": {
        "x": 500,
        "y": 250
      }
    },
    {
      "id": "flow-pollution-gen",
      "name": "Pollution Generation",
      "equation": "Population * Pollution_Normal * Pollution_Generation_Multiplier",
      "from_stock": null,
      "to_stock": "stock-pollution",
      "position": {
        "x": 250,
        "y": 350
      }
    },
    {
      "id": "flow-pollution-absorb",
      "name": "Pollution Absorption",
      "equation": "Pollution / Pollution_Absorption_Time",
      "from_stock": "stock-pollution",
      "to_stock": null,
      "position": {
        "x": 350,
        "y": 350
      }
    },
    {
      "id": "flow-agric-adjust",
      "name": "Agriculture Adjustment",
      "equation": "(Desired_Agric_Fraction - Capital_in_Agriculture_Fraction) / Agric_Adjustment_Time",
      "from_stock": null,
      "to_stock": "stock-agric-frac",
      "position": {
        "x": 100,
        "y": 400
      }
    }
  ],
  "variables": [
    {
      "id": "var-brn",
      "name": "Birth Rate Normal",
      "equation": "0.04",
      "position": {
        "x": 50,
        "y": 150
      }
    },
    {
      "id": "var-brm",
      "name": "Birth Rate Multiplier",
      "equation": "BRM_Material * BRM_Crowding * BRM_Food * BRM_Pollution",
      "position": {
        "x": 100,
        "y": 100
      }
    },
    {
      "id": "var-brm-mat",
      "name": "BRM Material",
      "equation": "1.2 - 0.8 * Material_Standard_of_Living / 5",
      "position": {
        "x": 50,
        "y": 50
      }
    },
    {
      "id": "var-brm-crowd",
      "name": "BRM Crowding",
      "equation": "1 - 0.5 * Crowding_Ratio",
      "position": {
        "x": 150,
        "y": 50
      }
    },
    {
      "id": "var-brm-food",
      "name": "BRM Food",
      "equation": "1 + 0.2 * (Food_Ratio - 1)",
      "position": {
        "x": 250,
        "y": 50
      }
    },
    {
      "id": "var-brm-poll",
      "name": "BRM Pollution",
      "equation": "1 - 0.3 * Pollution_Ratio",
      "position": {
        "x": 350,
        "y": 50
      }
    },
    {
      "id": "var-drn",
      "name": "Death Rate Normal",
      "equation": "0.028",
      "position": {
        "x": 150,
        "y": 150
      }
    },
    {
      "id": "var-drm",
      "name": "Death Rate Multiplier",
      "equation": "DRM_Material * DRM_Crowding * DRM_Food * DRM_Pollution",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "var-drm-mat",
      "name": "DRM Material",
      "equation": "0.6 + 0.4 / (Material_Standard_of_Living + 0.1)",
      "position": {
        "x": 50,
        "y": 250
      }
    },
    {
      "id": "var-drm-crowd",
      "name": "DRM Crowding",
      "equation": "1 + 0.5 * Crowding_Ratio",
      "position": {
        "x": 150,
        "y": 250
      }
    },
    {
      "id": "var-drm-food",
      "name": "DRM Food",
      "equation": "1 / (Food_Ratio + 0.1)",
      "position": {
        "x": 250,
        "y": 250
      }
    },
    {
      "id": "var-drm-poll",
      "name": "DRM Pollution",
      "equation": "1 + 0.5 * Pollution_Ratio",
      "position": {
        "x": 350,
        "y": 250
      }
    },
    {
      "id": "var-cgn",
      "name": "Capital Generation Normal",
      "equation": "0.05",
      "position": {
        "x": 250,
        "y": 150
      }
    },
    {
      "id": "var-cgm",
      "name": "Capital Generation Multiplier",
      "equation": "1",
      "position": {
        "x": 300,
        "y": 100
      }
    },
    {
      "id": "var-cnl",
      "name": "Capital Normal Lifetime",
      "equation": "40",
      "position": {
        "x": 350,
        "y": 150
      }
    },
    {
      "id": "var-run",
      "name": "Resource Usage Normal",
      "equation": "1",
      "position": {
        "x": 450,
        "y": 150
      }
    },
    {
      "id": "var-rum",
      "name": "Resource Usage Multiplier",
      "equation": "Material_Standard_of_Living",
      "position": {
        "x": 500,
        "y": 100
      }
    },
    {
      "id": "var-pn",
      "name": "Pollution Normal",
      "equation": "1",
      "position": {
        "x": 250,
        "y": 300
      }
    },
    {
      "id": "var-pgm",
      "name": "Pollution Generation Multiplier",
      "equation": "Material_Standard_of_Living",
      "position": {
        "x": 300,
        "y": 250
      }
    },
    {
      "id": "var-pat",
      "name": "Pollution Absorption Time",
      "equation": "100",
      "position": {
        "x": 350,
        "y": 300
      }
    },
    {
      "id": "var-msol",
      "name": "Material Standard of Living",
      "equation": "Capital_Investment / Population / 0.2",
      "position": {
        "x": 400,
        "y": 100
      }
    },
    {
      "id": "var-food-ratio",
      "name": "Food Ratio",
      "equation": "Capital_Investment * Capital_in_Agriculture_Fraction / Population / 0.1",
      "position": {
        "x": 200,
        "y": 400
      }
    },
    {
      "id": "var-crowd",
      "name": "Crowding Ratio",
      "equation": "Population / 3700000000",
      "position": {
        "x": 100,
        "y": 150
      }
    },
    {
      "id": "var-poll-ratio",
      "name": "Pollution Ratio",
      "equation": "Pollution / 350000000",
      "position": {
        "x": 400,
        "y": 350
      }
    },
    {
      "id": "var-res-ratio",
      "name": "Resource Ratio",
      "equation": "Natural_Resources / 900000000000",
      "position": {
        "x": 550,
        "y": 150
      }
    },
    {
      "id": "var-qol",
      "name": "Quality of Life",
      "equation": "(Material_Standard_of_Living * Food_Ratio) / ((Crowding_Ratio + 0.1) * (Pollution_Ratio + 0.1))",
      "position": {
        "x": 450,
        "y": 350
      }
    },
    {
      "id": "var-desired-agric",
      "name": "Desired Agric Fraction",
      "equation": "0.3 - 0.1 * Food_Ratio",
      "position": {
        "x": 50,
        "y": 400
      }
    },
    {
      "id": "var-agric-adj-time",
      "name": "Agric Adjustment Time",
      "equation": "15",
      "position": {
        "x": 150,
        "y": 400
      }
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 1900,
    "end": 2100,
    "dt": 1
  },
  "created_at": "2026-01-12T03:11:09.889436+00:00",
  "updated_at": "2026-01-12T03:11:09.889436+00:00"
}

{
  "id": "agricultural-water-demand-cli",
  "name": "Agricultural Water Demand Model",
  "description": "A system dynamics model of agricultural water demand and irrigation. Models the interactions between crop production, water availability, irrigation efficiency, and the feedback effects of water stress on yield and farmer adaptation. Reference: FAO AQUASTAT. Water resources and agricultural water management. Source: https://www.fao.org/aquastat/",
  "stocks": [
    {
      "id": "stock-soil-moisture",
      "name": "Soil Moisture",
      "initial_value": 200,
      "equation": "",
      "position": {
        "x": 300,
        "y": 150
      }
    },
    {
      "id": "stock-crop-biomass",
      "name": "Crop Biomass",
      "initial_value": 100,
      "equation": "",
      "position": {
        "x": 300,
        "y": 300
      }
    },
    {
      "id": "stock-irrigation-capacity",
      "name": "Irrigation Capacity",
      "initial_value": 50,
      "equation": "",
      "position": {
        "x": 550,
        "y": 150
      }
    },
    {
      "id": "stock-water-reservoir",
      "name": "Water Reservoir",
      "initial_value": 1000,
      "equation": "",
      "position": {
        "x": 100,
        "y": 150
      }
    },
    {
      "id": "stock-farm-revenue",
      "name": "Cumulative Farm Revenue",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 550,
        "y": 300
      }
    }
  ],
  "flows": [
    {
      "id": "flow-precipitation",
      "name": "Precipitation Input",
      "equation": "Base_Precipitation * (1 + 0.5 * SIN(TIME * 2 * 3.14159 / 12))",
      "from_stock": null,
      "to_stock": "stock-soil-moisture",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "flow-irrigation",
      "name": "Irrigation",
      "equation": "MIN(Irrigation_Demand, MIN(Irrigation_Capacity, Water_Reservoir / Time_Step))",
      "from_stock": "stock-water-reservoir",
      "to_stock": "stock-soil-moisture",
      "position": {
        "x": 200,
        "y": 150
      }
    },
    {
      "id": "flow-evapotranspiration",
      "name": "Evapotranspiration",
      "equation": "Potential_ET * MIN(1, Soil_Moisture / Field_Capacity) * Crop_Coefficient",
      "from_stock": "stock-soil-moisture",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 150
      }
    },
    {
      "id": "flow-deep-percolation",
      "name": "Deep Percolation",
      "equation": "MAX(0, Soil_Moisture - Field_Capacity) * Percolation_Rate",
      "from_stock": "stock-soil-moisture",
      "to_stock": null,
      "position": {
        "x": 300,
        "y": 50
      }
    },
    {
      "id": "flow-crop-growth",
      "name": "Crop Growth",
      "equation": "Potential_Growth * Water_Stress_Factor * Temperature_Factor",
      "from_stock": null,
      "to_stock": "stock-crop-biomass",
      "position": {
        "x": 200,
        "y": 300
      }
    },
    {
      "id": "flow-harvest",
      "name": "Harvest",
      "equation": "IF(MOD(TIME, 12) > 10, Crop_Biomass * Harvest_Fraction, 0)",
      "from_stock": "stock-crop-biomass",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 300
      }
    },
    {
      "id": "flow-capacity-investment",
      "name": "Capacity Investment",
      "equation": "Investment_Rate * Investment_Decision",
      "from_stock": null,
      "to_stock": "stock-irrigation-capacity",
      "position": {
        "x": 550,
        "y": 50
      }
    },
    {
      "id": "flow-capacity-depreciation",
      "name": "Capacity Depreciation",
      "equation": "Irrigation_Capacity / Infrastructure_Lifetime",
      "from_stock": "stock-irrigation-capacity",
      "to_stock": null,
      "position": {
        "x": 650,
        "y": 150
      }
    },
    {
      "id": "flow-reservoir-inflow",
      "name": "Reservoir Inflow",
      "equation": "River_Flow_Rate",
      "from_stock": null,
      "to_stock": "stock-water-reservoir",
      "position": {
        "x": 50,
        "y": 150
      }
    },
    {
      "id": "flow-revenue-generation",
      "name": "Revenue Generation",
      "equation": "Harvest * Crop_Price",
      "from_stock": null,
      "to_stock": "stock-farm-revenue",
      "position": {
        "x": 475,
        "y": 300
      }
    }
  ],
  "variables": [
    {
      "id": "var-base-precip",
      "name": "Base Precipitation",
      "equation": "30",
      "position": {
        "x": 100,
        "y": 50
      }
    },
    {
      "id": "var-potential-et",
      "name": "Potential ET",
      "equation": "50 * (1 + 0.3 * SIN(TIME * 2 * 3.14159 / 12))",
      "position": {
        "x": 250,
        "y": 50
      }
    },
    {
      "id": "var-field-capacity",
      "name": "Field Capacity",
      "equation": "300",
      "position": {
        "x": 400,
        "y": 50
      }
    },
    {
      "id": "var-wilting-point",
      "name": "Wilting Point",
      "equation": "100",
      "position": {
        "x": 550,
        "y": 50
      }
    },
    {
      "id": "var-crop-coefficient",
      "name": "Crop Coefficient",
      "equation": "0.8",
      "position": {
        "x": 700,
        "y": 50
      }
    },
    {
      "id": "var-percolation-rate",
      "name": "Percolation Rate",
      "equation": "0.1",
      "position": {
        "x": 100,
        "y": 400
      }
    },
    {
      "id": "var-irrigation-demand",
      "name": "Irrigation Demand",
      "equation": "MAX(0, (Target_Moisture - Soil_Moisture) * Irrigation_Efficiency)",
      "position": {
        "x": 250,
        "y": 400
      }
    },
    {
      "id": "var-target-moisture",
      "name": "Target Moisture",
      "equation": "Field_Capacity * 0.8",
      "position": {
        "x": 400,
        "y": 400
      }
    },
    {
      "id": "var-irrigation-efficiency",
      "name": "Irrigation Efficiency",
      "equation": "0.7",
      "position": {
        "x": 550,
        "y": 400
      }
    },
    {
      "id": "var-water-stress",
      "name": "Water Stress Factor",
      "equation": "MAX(0, MIN(1, (Soil_Moisture - Wilting_Point) / (Field_Capacity - Wilting_Point)))",
      "position": {
        "x": 700,
        "y": 400
      }
    },
    {
      "id": "var-potential-growth",
      "name": "Potential Growth",
      "equation": "20",
      "position": {
        "x": 100,
        "y": 500
      }
    },
    {
      "id": "var-temperature-factor",
      "name": "Temperature Factor",
      "equation": "0.8 + 0.2 * SIN(TIME * 2 * 3.14159 / 12)",
      "position": {
        "x": 250,
        "y": 500
      }
    },
    {
      "id": "var-harvest-fraction",
      "name": "Harvest Fraction",
      "equation": "0.9",
      "position": {
        "x": 400,
        "y": 500
      }
    },
    {
      "id": "var-crop-price",
      "name": "Crop Price",
      "equation": "2",
      "position": {
        "x": 550,
        "y": 500
      }
    },
    {
      "id": "var-investment-rate",
      "name": "Investment Rate",
      "equation": "5",
      "position": {
        "x": 700,
        "y": 500
      }
    },
    {
      "id": "var-investment-decision",
      "name": "Investment Decision",
      "equation": "IF(Water_Stress_Factor < 0.5, 1, 0)",
      "position": {
        "x": 100,
        "y": 600
      }
    },
    {
      "id": "var-infrastructure-lifetime",
      "name": "Infrastructure Lifetime",
      "equation": "20",
      "position": {
        "x": 250,
        "y": 600
      }
    },
    {
      "id": "var-river-flow",
      "name": "River Flow Rate",
      "equation": "100 * (1 + 0.3 * SIN(TIME * 2 * 3.14159 / 12))",
      "position": {
        "x": 400,
        "y": 600
      }
    },
    {
      "id": "var-time-step",
      "name": "Time Step",
      "equation": "1",
      "position": {
        "x": 550,
        "y": 600
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "Soil Moisture",
      "to_element": "Evapotranspiration"
    },
    {
      "id": "conn-2",
      "from_element": "Soil Moisture",
      "to_element": "Water Stress Factor"
    },
    {
      "id": "conn-3",
      "from_element": "Water Stress Factor",
      "to_element": "Crop Growth"
    },
    {
      "id": "conn-4",
      "from_element": "Crop Biomass",
      "to_element": "Harvest"
    },
    {
      "id": "conn-5",
      "from_element": "Irrigation Demand",
      "to_element": "Irrigation"
    },
    {
      "id": "conn-6",
      "from_element": "Irrigation Capacity",
      "to_element": "Irrigation"
    },
    {
      "id": "conn-7",
      "from_element": "Water Reservoir",
      "to_element": "Irrigation"
    },
    {
      "id": "conn-8",
      "from_element": "Water Stress Factor",
      "to_element": "Investment Decision"
    },
    {
      "id": "conn-9",
      "from_element": "Investment Decision",
      "to_element": "Capacity Investment"
    },
    {
      "id": "conn-10",
      "from_element": "Harvest",
      "to_element": "Revenue Generation"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 60,
    "dt": 0.25
  },
  "created_at": "2026-01-11T21:00:00.000000Z",
  "updated_at": "2026-01-11T21:00:00.000000Z",
  "source": "https://github.com/SDXorg/PySD-Cookbook",
  "reference": "SDXorg System Dynamics Model Repository"
}

{
  "id": "dice-integrated-assessment-model-simplified-cli",
  "name": "DICE Integrated Assessment Model (Simplified)",
  "description": "A simplified version of Nordhaus' Dynamic Integrated Climate-Economy (DICE) model. Links economic production, CO2 emissions, climate change, and climate damages in an integrated framework for policy analysis. Reference: Nordhaus, W. D. (2008). A question of balance. Yale University Press. DOI: https://doi.org/10.1093/reep/ren023",
  "stocks": [
    {
      "id": "stock-capital-stock",
      "name": "Capital Stock",
      "initial_value": 223000000000000.0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-atmospheric-co2",
      "name": "Atmospheric CO2",
      "initial_value": 851,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "stock-upper-ocean-co2",
      "name": "Upper Ocean CO2",
      "initial_value": 460,
      "equation": "",
      "position": {
        "x": 550,
        "y": 200
      }
    },
    {
      "id": "stock-deep-ocean-co2",
      "name": "Deep Ocean CO2",
      "initial_value": 1740,
      "equation": "",
      "position": {
        "x": 750,
        "y": 200
      }
    },
    {
      "id": "stock-atmospheric-temperature",
      "name": "Atmospheric Temperature",
      "initial_value": 0.85,
      "equation": "",
      "position": {
        "x": 150,
        "y": 350
      }
    },
    {
      "id": "stock-ocean-temperature",
      "name": "Ocean Temperature",
      "initial_value": 0.0068,
      "equation": "",
      "position": {
        "x": 350,
        "y": 350
      }
    },
    {
      "id": "stock-cumulative-industrial-emissions",
      "name": "Cumulative Industrial Emissions",
      "initial_value": 400,
      "equation": "",
      "position": {
        "x": 550,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-investment",
      "name": "Investment",
      "equation": "Savings_Rate * Net_Output",
      "from_stock": null,
      "to_stock": "stock-capital-stock",
      "position": {
